/**
 * What a printer's file browser reads from a file: the slicer line, the time
 * and filament estimates, and `M73` progress. The engine writes none of these
 * in the form Moonraker and Mainsail look for, so Export and Send add them.
 *
 * Moonraker reads the PrusaSlicer family by `; generated by NAME on DATE at
 * TIME`, then `; estimated printing time`, `; filament used [mm] = N` and the
 * other `; key = value` lines near the end of the file. Klipper turns
 * `M73 P<percent>` into `display_status.progress`, which Mainsail can show
 * instead of the file position.
 */

export interface PrintMeta {
  /** The export time, written as local date and time in the first line. */
  now: Date;
  version: string;
  /** Seconds of each printed layer, one per `;LAYER:` marker in file order. Empty: no `M73`. */
  layerSeconds: readonly number[];
  layerHeight?: number;
  nozzleDiameter?: number;
  filamentType?: string;
}

const ENGINE_HEADER = "; generated by Lime Slice — FDM strategy blender";
const LAYER = "\n;LAYER:";
const COOLDOWN = "M106 S0\nM104 S0\nM140 S0\n";
const ESTIMATE = /^; TIME:(\S+)s FILAMENT_MM:(\S+) FILAMENT_G:(\S+)/;

/** `gcode` with a header Moonraker identifies, footer estimates, and `M73` progress after each layer line whose percent moved. */
export function withPrintMeta(gcode: string, meta: PrintMeta): string {
  const body = engineBody(gcode);
  const head = `${headerLine(meta)}\n; FDM strategy blender\n`;
  const marks = layerMarks(body);
  const progress = marks.length > 0 && marks.length === meta.layerSeconds.length ? progressLines(meta.layerSeconds) : [];
  const timeAt = estimateAt(body);
  const estimate = timeAt >= 0 ? ESTIMATE.exec(body.slice(timeAt)) : null;

  const inserts: { at: number; text: string }[] = [];
  progress.forEach((line, i) => {
    if (line !== null) inserts.push({ at: marks[i]!, text: `${line}\n` });
  });
  if (progress.length > 0) inserts.push({ at: finishAt(body, marks[marks.length - 1]!, timeAt), text: "M73 P100 R0\n" });
  const footer = footerLines(meta, estimate);
  if (footer.length > 0) inserts.push({ at: footerAt(body), text: `${footer.join("\n")}\n` });

  inserts.sort((a, b) => a.at - b.at);
  const parts = [head];
  let from = 0;
  for (const { at, text } of inserts) {
    parts.push(body.slice(from, at), text);
    from = at;
  }
  parts.push(body.slice(from));
  return parts.join("");
}

/** The file without the engine's own first line, which the new header replaces. */
function engineBody(gcode: string): string {
  if (!gcode.startsWith(ENGINE_HEADER)) return gcode;
  const end = gcode.indexOf("\n");
  return end < 0 ? "" : gcode.slice(end + 1);
}

function headerLine(meta: PrintMeta): string {
  const d = meta.now;
  const two = (n: number) => String(n).padStart(2, "0");
  const date = `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())}`;
  const time = `${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`;
  return `; generated by Lime Slice ${meta.version} on ${date} at ${time}`;
}

/** The index just past each `;LAYER:` line, in order. One scan, no line array. */
function layerMarks(gcode: string): number[] {
  const marks: number[] = [];
  const next = (from: number) => {
    const at = gcode.indexOf(LAYER, from);
    return at < 0 ? -1 : at + 1;
  };
  for (let at = gcode.startsWith(LAYER.slice(1)) ? 0 : next(0); at >= 0; at = next(at)) {
    const end = gcode.indexOf("\n", at);
    if (end < 0) break;
    marks.push(end + 1);
  }
  return marks;
}

/**
 * The `M73` line for each layer, or `null` where the integer percent stays the
 * same as the last line written. The percent is the time before the layer
 * starts, so layer 0 is always 0.
 */
function progressLines(seconds: readonly number[]): (string | null)[] {
  const total = seconds.reduce((sum, s) => sum + s, 0);
  if (!(total > 0)) return [];
  let done = 0;
  let last = -1;
  return seconds.map((s) => {
    const percent = Math.min(100, Math.floor((done * 100) / total + 1e-9));
    const minutes = Math.max(0, Math.ceil((total - done) / 60 - 1e-9));
    done += s;
    if (percent === last) return null;
    last = percent;
    return `M73 P${percent} R${minutes}`;
  });
}

/** Where `M73 P100 R0` goes: ahead of the cooldown, so a printer's end block follows it. */
function finishAt(gcode: string, lastLayer: number, timeAt: number): number {
  const cooldown = gcode.lastIndexOf(COOLDOWN);
  if (cooldown >= lastLayer) return cooldown;
  return timeAt >= 0 ? timeAt : footerAt(gcode);
}

/** Where the engine's `; TIME:` line starts, or -1. */
function estimateAt(gcode: string): number {
  const at = gcode.lastIndexOf("; TIME:");
  return at === 0 || (at > 0 && gcode[at - 1] === "\n") ? at : -1;
}

/** Before the final `M84`, else the end of the file. */
function footerAt(gcode: string): number {
  const motors = gcode.lastIndexOf("\nM84\n");
  return motors >= 0 ? motors + 1 : gcode.length;
}

function footerLines(meta: PrintMeta, estimate: RegExpExecArray | null): string[] {
  const lines: string[] = [];
  if (estimate) {
    const seconds = Number(estimate[1]);
    if (Number.isFinite(seconds)) lines.push(`; estimated printing time (normal mode) = ${duration(Math.round(seconds))}`);
    lines.push(`; filament used [mm] = ${estimate[2]}`);
    const grams = Number(estimate[3]);
    if (Number.isFinite(grams)) lines.push(`; filament used [g] = ${grams.toFixed(2)}`);
  }
  if (meta.layerSeconds.length > 0) lines.push(`; total layers count = ${meta.layerSeconds.length}`);
  if (meta.layerHeight !== undefined) lines.push(`; layer_height = ${meta.layerHeight}`);
  if (meta.nozzleDiameter !== undefined) lines.push(`; nozzle_diameter = ${meta.nozzleDiameter}`);
  if (meta.filamentType) lines.push(`; filament_type = ${meta.filamentType}`);
  return lines;
}

/** "18h 25m 43s", the way PrusaSlicer writes it: leading zero units are left out. */
function duration(total: number): string {
  const d = Math.floor(total / 86400);
  const h = Math.floor((total % 86400) / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const units: [number, string][] = [[d, "d"], [h, "h"], [m, "m"]];
  const shown = units.filter(([n], i) => n > 0 || units.slice(0, i).some(([x]) => x > 0)).map(([n, u]) => `${n}${u}`);
  return [...shown, `${s}s`].join(" ");
}
